/// <summary>
/// MPJ_12961_BulkDataUpdates - 21/10/2021
/// Service class <c>METAPBulkUpdateService</c> which is executing the logic for invoice update
/// </summary>
using OfficeOpenXml;
using OfficeOpenXml.ExcelPackage;
using OfficeOpenXml.ExcelRange;
class METARBulkUpdateService extends SysOperationServiceBase
{
    #File
    NoYes                   dueDate, onHold;

    DataAreaId              dataAreadId;
    AccountNum              custAccNum;
    CustInvoiceId           custInvoiceId;
    AmountCurDebCred        amountCur;
    DueDate                 originalDueDate, updatedDueDate;
    CustVendDisputeStatus   collectionStatus;
    NoYes                   recordAction, createFollowUpTask;
    ReasonCode              reasonCode;
    smmActivityUserMemo     note;
    TransDate               followUpDate;
    AmountCur               disputedAmount;

    CustTransOpen           custtransOpen;
    CustTrans               custTrans;
    ReasonTable             reasonTable;
    ReasonTableRef          reasonTableRef;
    CustDispute             custDispute;

    recId                   custRecId;

    
}

Method.Source:
    /// <summary>
    /// AR Invoice update logic
    /// </summary>
    /// <param name = "_contract">Instance of the <c>METAPBulkUpdateContract</c> class</param>
    public void processOperation(METBulkUpdateContract _contract)
    {
        System.IO.Stream     stream;

        if (_contract.parmStorageResult() != conNull())
        {
            FileUploadTemporaryStorageResult fileUploadResult = new FileUploadTemporaryStorageResult();

            fileUploadResult.unpack(_contract.parmStorageResult());

            if (fileUploadResult != null)
            {
                try
                {
                    dueDate = _contract.parmDueDate();
                    onHold = _contract.parmOnHold();

                    stream = File::UseFileFromURL(fileUploadResult.getDownloadUrl());
                    this.readExcelData(stream);

                    Info("@MET:FileProcessed");
                }
                catch (Exception::Error)
                {
                    error("@RET433");
                }
            }
        }
    }

    /// <summary>
    /// Parse excel file
    /// </summary>
    /// <param name = "_stream">Excel upload stream</param>
    public void readExcelData(System.IO.Stream _stream)
    {
        OfficeOpenXml.ExcelWorksheet        worksheet;
        OfficeOpenXml.ExcelRange            cells;
        OfficeOpenXml.ExcelPackage          package = new OfficeOpenXml.ExcelPackage(_stream);

        int         totalRows,totalCells,rowCounter,cellCounter;
        container   currentLine;

        if(package)
        {
            worksheet       = package.get_Workbook().get_Worksheets().get_Item(1);
            cells           = worksheet.Cells;
            totalRows       = worksheet.Dimension.End.Row ;
            totalCells      = worksheet.Dimension.End.Column;

            for (rowCounter = 2; rowCounter<= totalRows; rowCounter++)
            {
                currentLine = conDel(currentLine, 1, conLen(currentLine));

                for (cellCounter=1; cellCounter<=totalCells; cellCounter++)
                {
                    currentLine = conIns(currentLine, cellCounter, cells.get_Item(rowCounter, cellCounter).value);
                }

                this.readLine(currentLine);
            }
        }

    }

    /// <summary>
    /// Row detail is read and updated in dynamics
    /// </summary>
    /// <param name = "_currentLine">Container containing row details</param>
    public void readLine(container _currentLine)
    {
        CustCollectionsSetTransactionStatusContext  context;
        CustCollectionsSetTransactionStatusHelper   statusHelper;
                
        dataAreadId             = conPeek(_currentLine, 1);
        custAccNum              = conPeek(_currentLine, 2);
        custInvoiceId           = conPeek(_currentLine, 3);
        amountCur               = conPeek(_currentLine, 4);
        originalDueDate         = conPeek(_currentLine, 5);
        updatedDueDate          = conPeek(_currentLine, 6);
        if (conPeek(_currentLine, 7))
        {
            collectionStatus        = str2Enum(collectionStatus,    conPeek(_currentLine, 7));  // CustVendDisputeStatus
        }

        if (conPeek(_currentLine, 8))
        {
            recordAction            = str2Enum(recordAction,        conPeek(_currentLine, 8));  // (Y/N)
        }

        if (conPeek(_currentLine, 9))
        {
            createFollowUpTask      = str2Enum(createFollowUpTask,  conPeek(_currentLine, 9));   // (Y/N)
        }

        note                    = conPeek(_currentLine, 10);
        reasonCode              = conPeek(_currentLine, 11);  
        followUpDate            = conPeek(_currentLine, 12);
        disputedAmount          = conPeek(_currentLine, 13);
        

        changecompany (dataAreadId)
        {
            if (updatedDueDate && dueDate == NoYes::Yes)
            {
                this.updateDueDate();
            }
            
            
            if (onHold == NoYes::Yes)
            {
                while select
                //    recid,
                //    amountcur,
                //    currencycode
                //from
                    custTrans
                exists join 
                    custtransOpen
                where
                    custtransOpen.REFRECID               == custTrans.RECID
                     && custtransOpen.DATAAREAID         == dataAreadId
                     && custtransOpen.ACCOUNTNUM         == custAccNum
                     && custTrans.INVOICE                == custInvoiceId
                     && custTrans.AmountCur              == amountCur
                     && custTrans.APPROVED               == NoYes::Yes
                     && (custTrans.TRANSTYPE             == LedgerTransType::None
                      || custTrans.TRANSTYPE             == LedgerTransType::Sales
                      || custTrans.TRANSTYPE             == LedgerTransType::CollectionLetter
                      || custTrans.TRANSTYPE             == LedgerTransType::Project
                      || custTrans.TRANSTYPE             == LedgerTransType::Cust
                      || custTrans.TRANSTYPE             == LedgerTransType::Interest
                      || custTrans.TRANSTYPE             == LedgerTransType::Transfer
                      || custTrans.TRANSTYPE             == LedgerTransType::GeneralJournal)
                {               
                    custDispute = custDispute::findByCustTrans(custTrans.RecId);
                    

                    if (!CustDispute)
                    {
                        reasonTable    = ReasonTable::find(reasonCode);

                        ttsbegin;
                        reasonTableRef.Reason = reasonCode;
                        reasonTableRef.ReasonComment = reasonTable.Description;
                        reasonTableRef.insert();

                        custDispute.initValue();
                        custDispute.CustTrans           = custTrans.RecId;
                        custDispute.ReasonTableRef      = reasonTableRef.RecId;
                        custDispute.Status              = collectionStatus;
                        custDispute.StatusChangedDate   = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
                        custDispute.FollowUpDate        = followUpDate;
                        custDispute.AmountCur           = disputedAmount;
                        custDispute.TransactionBalance  = disputedAmount;
                        custDispute.TransactionCurrency = custTrans.CurrencyCode;
                        custDispute.note                = note;
                        custDispute.insert();
                        ttscommit;

                        custRecId = (select firstonly custTable where custTable.AccountNum == custTrans.AccountNum).RecId;

                        if (recordAction == NoYes::Yes)
                        {
                            context     = this.createContext(recordAction);
                            CustCollectionsSetTransactionStatusHelper::createActivity(custTrans, custRecId, context, smmActivityCategory::Action);
                        }

                        if (createFollowUpTask == NoYes::Yes && 
                            (collectionStatus != CustVendDisputeStatus::Resolved || 
                             collectionStatus != CustVendDisputeStatus::PromiseToPayKept ||
                             collectionStatus != CustVendDisputeStatus::None))
                        {
                            context     = this.createContext(createFollowUpTask);
                            CustCollectionsSetTransactionStatusHelper::createActivity(custTrans, custRecId, context, smmActivityCategory::Task);
                        }
                    }
                    else
                    {
                        transdate changeDate  = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());

                        this.updateCustDispute(changeDate);

                        reasonTable    = ReasonTable::find(reasonCode);

                        if (reasonTable)
                        {
                            this.updateReasonTable();
                        }

                        if (recordAction == NoYes::Yes)
                        {
                            context     = this.createContext(recordAction);
                            CustCollectionsSetTransactionStatusHelper::createActivity(custTrans, custRecId, context, smmActivityCategory::Action);
                        }

                        if (createFollowUpTask == NoYes::Yes &&
                            (collectionStatus != CustVendDisputeStatus::Resolved ||
                             collectionStatus != CustVendDisputeStatus::PromiseToPayKept ||
                             collectionStatus != CustVendDisputeStatus::None))
                        {
                            context     = this.createContext(createFollowUpTask);
                            CustCollectionsSetTransactionStatusHelper::createActivity(custTrans, custRecId, context, smmActivityCategory::Task);
                        }
                    }
                }
            }
        }
    }

    private CustCollectionsSetTransactionStatusContext createContext(NoYes _state)
    {
        CustCollectionsSetTransactionStatusContext context = CustCollectionsSetTransactionStatusContext::contruct();

        context.parmReasonCode(reasonCode);
        context.parmReasonComment(reasonTable.Description);
        context.parmAmountCur(disputedAmount);
        context.parmFollowUpDate(followUpDate);
        context.parmStatus(collectionStatus);
        context.parmNote(note);
        context.parmUseUserMemo(_state);
        context.parmRecordAction(_state);
        context.parmCreateTask(_state);

        return context;
    }

private void updateReasonTable()
{
    update_recordset
        reasonTableRef
    setting
        Reason = reasonCode,
        ReasonComment = reasonTable.Description
    join custDispute
        where
            custDispute.ReasonTableRef == reasonTableRef.RecId
            && custDispute.CustTrans    == custTrans.RecId;
}
